package com.jnapanam.sportszone.usermanagement.model;import com.jnapanam.sportszone.identity.model.User;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity@Table(name="user_admin_notes")public class UserAdminNote{@Id private UUID id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="user_id")private User user;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="author_user_id")private User author;@Column(nullable=false,length=1000)private String note;@Column(name="created_at",nullable=false)private Instant createdAt;protected UserAdminNote(){}public UserAdminNote(User u,User a,String n){id=UUID.randomUUID();user=u;author=a;note=n.trim();createdAt=Instant.now();}public UUID getId(){return id;}public String getNote(){return note;}public User getAuthor(){return author;}public Instant getCreatedAt(){return createdAt;}}
